import{_ as a,o as n,a as p,b as l}from"./app.UgfkfLuP.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"原子操作","link":"/api/SIMD-API/tensor_api/atomic/atomic"},{"text":"set_atomic_min","link":"/api/SIMD-API/tensor_api/atomic/set_atomic_min"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/atomic/set_atomic_min.md","filePath":"api/SIMD-API/tensor_api/atomic/set_atomic_min.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1793173587000}'),c={name:"api/SIMD-API/tensor_api/atomic/set_atomic_min.md"};function t(e,s,i,o,_,d){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>set_atomic_min</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR&amp;950DT系列产品：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>。</p><p>原子比较取小过程：将待搬运到GM的数据和GM上已有数据进行比较，然后将两者中的最小值写入GM。本接口对后续目的地址为GM的数据搬运指令开启原子比较取小。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">set_atomic_min</span><span class="p">()</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">T</td><td align="left">原子取小的数据类型。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p><code>T</code>支持<code>int8_t</code>、<code>int16_t</code>、<code>int32_t</code>、<code>half</code>、<code>bfloat16_t</code>和<code>float</code>。</p><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>支持的数据通路为UB/L0C Buffer-&gt;GM。</li><li>开启后对后续所有目的地址为GM的搬运指令生效，可以调用<a href="disable_dma_atomic.html"><code>disable_dma_atomic</code></a>关闭。</li><li>本接口执行前不会自动将GM上已有数据置零。若期望原子取小前GM上的原始数据为零，需手动清零。</li><li>本接口仅对后续通过MTE1/MTE2/MTE3单元搬运且目的地址为GM的搬运指令生效，对标量写GM指令不生效。</li><li>后续搬运指令的操作数据类型必须与<code>T</code>一致。</li><li>本接口不能保证后续搬运指令的执行顺序。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>以下示例先读取Global Memory上的初始值，再通过DMA原子取最小值将输入数据与初始值计算后写回Global Memory，最后关闭原子模式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&lt;cstdint&gt;</span>

<span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">total_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>

<span class="n">__global__</span><span class="w"> </span><span class="n">__vector__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">atomic_min_kernel</span><span class="p">(</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">output</span><span class="p">,</span><span class="w"> </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">float</span><span class="o">*</span><span class="w"> </span><span class="n">input</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="k">using</span><span class="w"> </span><span class="k">namespace</span><span class="w"> </span><span class="nn">asc</span><span class="o">::</span><span class="nn">te</span><span class="p">;</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">input_buffer</span><span class="p">[</span><span class="n">total_length</span><span class="p">];</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="kt">float</span><span class="w"> </span><span class="n">output_buffer</span><span class="p">[</span><span class="n">total_length</span><span class="p">];</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">nd_ext_layout_ptn</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="n">total_length</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">input_gm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">gm</span><span class="o">&gt;</span><span class="p">(</span><span class="n">input</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">output_gm</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">location</span><span class="o">::</span><span class="n">gm</span><span class="o">&gt;</span><span class="p">(</span><span class="n">output</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">input_ub</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">input_buffer</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">output_ub</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">make_tensor</span><span class="p">(</span><span class="n">make_mem_ptr</span><span class="p">(</span><span class="n">output_buffer</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>

<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_gm_to_ub</span><span class="p">{}),</span><span class="w"> </span><span class="n">input_ub</span><span class="p">,</span><span class="w"> </span><span class="n">input_gm</span><span class="p">);</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_gm_to_ub</span><span class="p">{}),</span><span class="w"> </span><span class="n">output_ub</span><span class="p">,</span><span class="w"> </span><span class="n">output_gm</span><span class="p">);</span>

<span class="w">    </span><span class="n">set_atomic_min</span><span class="o">&lt;</span><span class="kt">float</span><span class="o">&gt;</span><span class="p">();</span>
<span class="w">    </span><span class="n">copy</span><span class="p">(</span><span class="n">make_copy</span><span class="p">(</span><span class="n">copy_ub_to_gm</span><span class="p">{}),</span><span class="w"> </span><span class="n">output_gm</span><span class="p">,</span><span class="w"> </span><span class="n">input_ub</span><span class="p">);</span>
<span class="w">    </span><span class="n">disable_dma_atomic</span><span class="p">();</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const h=a(c,[["render",t]]);export{u as __pageData,h as default};
